import{_ as s,C as o,o as t,c as l,j as a,a as r,b as d,w as i,E as c,a2 as h,a3 as g}from"./chunks/framework.pb1iZPmZ.js";const A=JSON.parse('{"title":"14.12 System Design: Search Systems & AI Request Pipelines","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.12-search-ai-architecture.md","filePath":"system-design/14.12-search-ai-architecture.md"}'),u={name:"system-design/14.12-search-ai-architecture.md"};function p(m,e,f,y,x,I){const n=o("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a("h1",{id:"_14-12-system-design-search-systems-ai-request-pipelines",tabindex:"-1"},[r("14.12 System Design: Search Systems & AI Request Pipelines "),a("a",{class:"header-anchor",href:"#_14-12-system-design-search-systems-ai-request-pipelines","aria-label":'Permalink to "14.12 System Design: Search Systems & AI Request Pipelines"'},"​")],-1)),(t(),d(h,null,{default:i(()=>[c(n,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Client%5B%22Clinician%20Dashboard%22%5D%0A%20%20%20%20%20%20%20%20Query%5B%22Search%20%2F%20AI%20Intake%20Input%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SearchTier%5B%22Search%20%26%20Retrieval%20Tier%22%5D%0A%20%20%20%20%20%20%20%20MongoText%5B%22MongoDB%20Text%20Index%20(Small%20Scale)%22%5D%0A%20%20%20%20%20%20%20%20Meili%5B%22Meilisearch%20%2F%20Elasticsearch%20(Fuzzy%20Typo-Tolerant%20Search)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20AIPipeline%5B%22Asynchronous%20AI%20Request%20Pipeline%22%5D%0A%20%20%20%20%20%20%20%20Queue%5B%22BullMQ%20AI%20Request%20Queue%22%5D%0A%20%20%20%20%20%20%20%20LLM%5B%22Pre-Trained%20Medical%20LLM%20(Gemini%201.5%20%2F%20Claude%203.5)%22%5D%0A%20%20%20%20%20%20%20%20Cache%5B(%22Redis%20Prompt%2FResponse%20Cache%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Query%20--%3E%20MongoText%20%26%20Meili%0A%20%20%20%20Query%20--%3E%20Queue%20--%3E%20Cache%20--%3E%20LLM%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=g('<hr><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Search architecture deals with retrieving relevant records across massive textual databases using inverted indexes, stemming, and fuzzy matching. AI architecture manages how user prompts are structured, queued, cached, filtered, and sent to LLM inference engines with strict cost and latency controls.</p><hr><h2 id="_2-whether-and-how-this-project-uses-it" tabindex="-1">2. Whether and How THIS Project Uses It <a class="header-anchor" href="#_2-whether-and-how-this-project-uses-it" aria-label="Permalink to &quot;2. Whether and How THIS Project Uses It&quot;">​</a></h2><p>In the current codebase:</p><ul><li><strong>Search</strong>: <strong>Not Used</strong>. User queries are point lookups (<code>User.findOne({ username })</code>).</li><li><strong>AI Integration</strong>: <strong>Not Used</strong>. No machine learning models or generative AI APIs are called.</li><li><strong>Reasoning</strong>: An authentication portal requires exact string matching for credentials, where fuzzy search or non-deterministic AI generation would introduce security flaws [CONFIRM WITH DEVELOPER].</li></ul><hr><h2 id="_3-search-engine-technologies-comparison" tabindex="-1">3. Search Engine Technologies Comparison <a class="header-anchor" href="#_3-search-engine-technologies-comparison" aria-label="Permalink to &quot;3. Search Engine Technologies Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Technology</th><th style="text-align:left;">Index Structure</th><th style="text-align:left;">Latency</th><th style="text-align:left;">Typo Tolerance</th><th style="text-align:left;">Operational Complexity</th><th style="text-align:left;">Fit for This Portal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>MongoDB Text Index</strong></td><td style="text-align:left;"><strong>B-Tree Text Index</strong></td><td style="text-align:left;"><strong>~10–20ms</strong></td><td style="text-align:left;"><strong>Basic stemming</strong></td><td style="text-align:left;"><strong>Zero (Built into existing MongoDB)</strong></td><td style="text-align:left;"><strong>Sufficient for staff directory</strong></td></tr><tr><td style="text-align:left;"><strong>Meilisearch</strong></td><td style="text-align:left;">Inverted Index in Rust</td><td style="text-align:left;">&lt;5ms</td><td style="text-align:left;">Excellent typo tolerance</td><td style="text-align:left;">Low (Single binary)</td><td style="text-align:left;">Recommended for clinical patient lookup</td></tr><tr><td style="text-align:left;"><strong>Elasticsearch</strong></td><td style="text-align:left;">Lucene Inverted Index</td><td style="text-align:left;">~10ms</td><td style="text-align:left;">Advanced NLP</td><td style="text-align:left;">Very High (JVM cluster)</td><td style="text-align:left;">Overkill for basic staff directory</td></tr><tr><td style="text-align:left;"><strong>Algolia</strong></td><td style="text-align:left;">Hosted SaaS Index</td><td style="text-align:left;">&lt;10ms</td><td style="text-align:left;">World-class</td><td style="text-align:left;">Managed SaaS</td><td style="text-align:left;">Prohibitive cost and third-party data privacy risks</td></tr></tbody></table><hr><h2 id="_4-ai-pipeline-architecture-for-healthcare" tabindex="-1">4. AI Pipeline Architecture for Healthcare <a class="header-anchor" href="#_4-ai-pipeline-architecture-for-healthcare" aria-label="Permalink to &quot;4. AI Pipeline Architecture for Healthcare&quot;">​</a></h2><p>If adding clinical triage or diagnostic assistance:</p><ol><li><strong>Prompt Sanitization &amp; De-Identification</strong>: Filter out direct patient identifiers (names, Social Security numbers) to comply with HIPAA Safe Harbor de-identification rules.</li><li><strong>Semantic Caching with Redis</strong>: If two clinicians submit identical symptom queries (e.g. standard fever dosages), serve the cached response from Redis in 2ms, avoiding expensive model inference costs and API token usage.</li><li><strong>Queue-Based Rate Leveling</strong>: Route requests through a Redis queue (BullMQ) to prevent exceeding cloud provider rate limits (TPM / RPM).</li></ol><hr><h2 id="_5-what-breaks-first-at-scale" tabindex="-1">5. What Breaks First at Scale <a class="header-anchor" href="#_5-what-breaks-first-at-scale" aria-label="Permalink to &quot;5. What Breaks First at Scale&quot;">​</a></h2><ul><li><strong>10x Load</strong>: Handled fine.</li><li><strong>100x Load</strong>: Un-cached AI calls would hit external provider rate limits, returning HTTP 429 errors to doctors.</li><li><strong>1000x Load</strong>: Synchronous AI requests freeze Express worker threads while awaiting LLM tokens.</li></ul><hr><h2 id="_6-senior-engineering-improvements" tabindex="-1">6. Senior Engineering Improvements <a class="header-anchor" href="#_6-senior-engineering-improvements" aria-label="Permalink to &quot;6. Senior Engineering Improvements&quot;">​</a></h2><p>Deploy <strong>Meilisearch</strong> for instant staff directory and patient record lookups; implement a queued AI request pipeline with Redis semantic caching and streaming responses via Server-Sent Events (SSE).</p><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Currently, the portal relies on exact MongoDB queries rather than fuzzy search or AI models. If we expand into clinical patient search, I would integrate Meilisearch for typo-tolerant, sub-five-millisecond lookups. For AI assistance, I would build an asynchronous pipeline using BullMQ to queue inference requests, cache repeated medical queries in Redis, and stream tokens to the UI using Server-Sent Events.&quot;</p></blockquote>',23))])}const b=s(u,[["render",p]]);export{A as __pageData,b as default};
